def 登录自检():
    内容 = page.content()                    # 整页 HTML，用来判断有没有登录
    @当前网址 = current_url                    # 等号左边＝写回变量清单
    @是否登录 = '是' if 'Logout' in 内容 else '否'
    log('当前网址：' + @当前网址)
    log('登录状态：' + @是否登录)
    return @是否登录

def 整理名言():
    import re
    原句 = @loop.item.名言
    干净 = re.sub(r'\s+', ' ', 原句).strip()      # 去掉多余的空白和换行
    现数 = int(@爱因斯坦条数 or 0)
    @爱因斯坦条数 = str(现数 + 1)                 # 循环里累加，跨轮保留
    @爱因斯坦名言 = @爱因斯坦名言 + 干净 + ' ｜ '
    log('第 %d 条爱因斯坦名言：%s' % (现数 + 1, 干净))
    return @爱因斯坦条数

def 清洗素材(#关键词表={{关键词表路径}}):
    # 关键词表是一个 csv：第一行是表头，后面每行一个词
    with open(关键词表, encoding='utf-8') as f:
        词表 = [x.strip() for x in f.read().splitlines()[1:] if x.strip()]
    正文 = @loop.item.内容
    干净 = ' '.join(正文.split())              # 把换行、多余空格压成一个空格
    命中 = [w for w in 词表 if w in 干净.lower()]
    现命中 = int(@命中数 or 0)
    if 命中:
        现命中 += 1
    @命中数 = str(现命中)                       # 循环里累加，跨轮保留
    @素材行数 = str(int(@素材行数 or 0)
                    + len([x for x in 正文.splitlines() if x.strip()]))
    @素材总数 = @loop.item.总数                  # 「读取数据」给的字段：一共几个文件
    @素材汇总 = @素材汇总 + '【%s】%s\n' % (@loop.item.文件名, 干净)
    log('%s：命中关键词 %s' % (@loop.item.文件名, '、'.join(命中) or '（无）'))
    return 干净
